      "expanded": "教皇是编号 5——皇帝建立的世俗秩序，在这里进入精神与文化的层面：传承、信仰、共同的价值体系。他坐在两根柱子之间,向两位门徒传授知识。这团能量的核心是「有些智慧不必从零摸索,前人和体系已经铺好了路,先学会规则再谈突破」。它关乎导师、教育、仪式、归属感,以及在一个更大的传统里找到自己的位置。"
