    "reviewNotes": "",
    "coreEnergy": {
      "oneLine": "听见召唤，从旧的自己中重生。",
      "expanded": "审判是号角吹响的时刻——那些沉睡在棺椁里的人，被一种更高的声音唤醒，起身、张开双臂、准备迎接新生。这股能量的方向是「向上、觉醒、清算与和解」：它要求你诚实地回顾走过的路，为自己下一个真实的裁决，然后放下过去、应答召唤。它的张力在于——重生的前提是先直面全部的自己，包括那些你一直不愿看的部分。在愚人之旅接近终点的位置，审判是脱胎换骨前的最后一次彻底觉醒，紧接着才是世界(21)的圆满。"
    },
